-- pre-M2b / rulings R79 and R80, generated by drizzle-kit and corrected by hand:
-- the rebuild's INSERT ... SELECT copies only the eight columns the old table
-- has. The four new ones (consecutive_blocked, verdict_before_block,
-- credential_state, notice) start at their defaults for every source.
PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_source_state` (
	`source_id` text PRIMARY KEY NOT NULL,
	`last_run_at` integer,
	`last_success_at` integer,
	`next_due_at` integer NOT NULL,
	`consecutive_failures` integer DEFAULT 0 NOT NULL,
	`backoff_until` integer,
	`last_error_kind` text,
	`last_error_message` text,
	`consecutive_blocked` integer DEFAULT 0 NOT NULL,
	`verdict_before_block` text,
	`credential_state` text,
	`notice` text,
	FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "source_state_consecutive_blocked_check" CHECK("consecutive_blocked" >= 0),
	CONSTRAINT "source_state_verdict_before_block_check" CHECK("verdict_before_block" is null or "verdict_before_block" in ('APPROVED', 'APPROVED_WITH_LIMITS', 'MANUAL_IMPORT_ONLY', 'PENDING_REVIEW', 'BLOCKED')),
	CONSTRAINT "source_state_credential_state_check" CHECK("credential_state" is null or "credential_state" in ('EXPIRED', 'INVALID')),
	CONSTRAINT "source_state_last_error_kind_check" CHECK("last_error_kind" is null or "last_error_kind" in ('NETWORK', 'DNS', 'TLS', 'TIMEOUT', 'HTTP_4XX', 'HTTP_5XX', 'BLOCKED', 'RATE_LIMITED', 'ROBOTS_DISALLOWED', 'PARSE', 'SCHEMA_CHANGED', 'UNKNOWN')),
	CONSTRAINT "source_state_consecutive_failures_check" CHECK("consecutive_failures" >= 0)
);
